const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human = v => String(v ?? 'Awaiting inference').replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const pct = v => v == null ? '—' : `${(v*100).toFixed(1)}%`;
const num = v => v == null ? '—' : Number(v).toLocaleString('en-GB');
const statuses = ['VOTABLE','NOT_VOTABLE','VOTABLE_WITH_RESTRICTION','POA_REQUIRED','SHARE_BLOCKING','DEADLINE_PASSED','UNCERTAIN_MANUAL_REVIEW'];
let state = {page:'overview',tablePage:1,filters:{},run:null,detail:null,split:'test',errorMode:'all',errorGroup:'predicted',experimentErrors:false,experimentModel:'fine-tuned',experimentDataset:'challenge',experimentField:'',experimentMin:0,experimentExpected:'',experimentPredicted:''};
let renderGeneration = 0;
let facets = {};
async function api(path,options={}) {
 const response = await fetch(`/api/${path}`,{...options,headers:{'Content-Type':'application/json',...options.headers}});
 if(!response.ok) {const data = await response.json().catch(()=>({detail:'Request failed'}));throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));}
 return response.json();
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function bars(){ $$('[data-width]').forEach(el=>el.style.width=`${Math.max(0,Math.min(100,Number(el.dataset.width)))}%`);$$('[data-height]').forEach(el=>el.style.height=`${Math.max(0,Math.min(100,Number(el.dataset.height)))}%`); }
function badge(v){return `<span class="badge ${esc(v||'')}">${esc(human(v))}</span>`;}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(subtitle)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,note,teal=false){return `<div class="metric"><div class="metric-label">${esc(label)}</div><div class="metric-value ${teal?'teal':''}">${esc(value)}</div><small>${esc(note)}</small></div>`;}
function empty(title,text,link=''){return `<div class="empty"><strong>${esc(title)}</strong><span>${esc(text)}</span>${link}</div>`;}
function panel(title,body,sub=''){return `<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2><small>${esc(sub)}</small></div>${body}</section>`;}
function notice(text,warning=false){return `<div class="notice ${warning?'warning':''}"><span class="label">${warning?'VALIDATION REQUIRED':'RESEARCH NOTE'}</span><div>${text}</div></div>`;}
function exportLink(kind='results'){return `<a class="button" href="/api/export?kind=${kind}${state.run?'&run_id='+encodeURIComponent(state.run):''}" download>Export ${kind}</a>`;}
function runQuery(){return state.run?`run_id=${encodeURIComponent(state.run)}`:'';}
function probabilityRows(scores){return Object.entries(scores).map(([k,v])=>`<div class="bar-row"><span>${esc(human(k))}</span><div class="bar-track"><div class="bar-fill" data-width="${v*100}"></div></div><span class="bar-number">${pct(v)}</span></div>`).join('');}
function rowTable(data,compact=false){
 if(!data.items.length)return empty('No matching notices','Try changing your search or filters.');
 return `<div class="table-wrap"><table><thead><tr><th>Issuer / Source ID</th><th>Document type</th>${compact?'':'<th>Market</th><th>ISIN / Meeting</th>'}<th>AI status</th><th>Policy score</th><th>Review status</th></tr></thead><tbody>${data.items.map(r=>`<tr class="clickable" data-record="${esc(r.id)}" tabindex="0" aria-label="Open ${esc(r.issuer)}"><td><div class="issuer">${esc(r.issuer||'Unknown issuer')}</div><span class="sub">${esc(r.id)}</span></td><td>${esc(r.event_type)}<span class="sub">${esc(r.language)} · ${esc(r.split)}</span></td>${compact?'':`<td>${esc(r.market||'Unknown')}</td><td>${esc(r.isin||'Not supplied')}<span class="sub">${esc(r.meeting_date||'Not supplied')}</span></td>`}<td>${badge(r.classification)}</td><td class="confidence">${pct(r.confidence)}</td><td><span class="review-pill ${r.review_status==='Verified'?'verified':''}">${esc(r.review_status)}</span>${r.correct===false?'<span class="sub cell-error">Prediction differs</span>':''}</td></tr>`).join('')}</tbody></table></div>`;
}
function bindRows(root=document){$$('[data-record]',root).forEach(r=>{r.addEventListener('click',()=>openNotice(r.dataset.record));r.addEventListener('keydown',e=>{if(e.key==='Enter')openNotice(r.dataset.record);});});}
function layerMetricCards(evidence){
 return panel('Accuracy by processing stage',`<div class="metrics layer-metrics">${Object.values(evidence.layers).map(r=>metric(r.title,r.accuracy==null?'Not measured':pct(r.accuracy),`${r.correct} / ${r.total} ${r.unit}`)).join('')}</div><div class="panel-body"><p>${esc(evidence.scope)}</p>${Object.values(evidence.layers).map(r=>`<p><strong>${esc(r.title)}:</strong> ${esc(r.definition)} ${esc(r.reason||'')}</p>`).join('')}<a class="evidence-link" href="/api/metric-layers?${runQuery()}" target="_blank" rel="noopener">View metric definitions and denominators</a></div>`,'Separate reference labels, denominators and error sources');
}
async function overview(){
 const [d, recent, runs, examples] = await Promise.all([api(`overview?${runQuery()}`),api(`notices?page_size=6&${runQuery()}`),api('runs'),api('demo')]);
 const run=runs.find(r=>r.id===d.run_id), b=run?.benchmark;
 const maxBin=Math.max(1,...d.confidence_bins);
 return heading('Decision operations','Voting intelligence','A measurable view of specialised, local AI for shareholder voting.',exportLink())+
 notice(`<strong>Public example corpus.</strong> ${num(d.total)} filing excerpts, including proxy statements and contract distractors. Human verification is required before measuring accuracy. Automation is disabled.`)+
 `<div class="metrics">${metric('Notices analysed',num(d.analysed),`${num(d.total)} source rows imported`,true)}${metric('Automatically processed',pct(d.analysed?d.auto/d.analysed:null),'Policy disabled pending validation')}${metric('Sent to human review',pct(d.analysed?d.manual/d.analysed:null),`${num(d.manual)} classified records`)}${metric('Reviewed test notices',num(d.verified_test),'Factor reviews; no event-level accuracy claim')}</div>`+
 layerMetricCards(d.metric_layers)+await hybridSummaryPanel(false)+
 (run?.status==='RUNNING'?notice(`Baseline in progress: <strong>${num(d.analysed)} / ${num(d.total)}</strong> persisted results. Refresh to see progress.`):'')+
 `<div class="grid">${panel('Classification distribution',Object.keys(d.distribution).length?`<div class="panel-body">${Object.entries(d.distribution).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`<div class="bar-row"><span>${esc(human(k))}</span><div class="bar-track"><div class="bar-fill" data-width="${n/Math.max(1,d.analysed)*100}"></div></div><span class="bar-number">${num(n)}</span></div>`).join('')}</div>`:empty('Awaiting baseline','Start a local Laya batch from Model runs.'),'AI predictions · unverified')}
 ${panel('Decision score distribution',`<div class="panel-body"><div class="histogram">${d.confidence_bins.map((v,i)=>`<div class="hist-item"><span>${num(v)||''}</span><div class="hist-bar" data-height="${v/maxBin*85}" title="${i*10}–${i*10+10}%: ${v}"></div></div>`).join('')}</div><div class="hist-labels"><span>0%</span><span>50%</span><span>100%</span></div><div class="chart-caption">Minimum winning factor probability. This is a policy score, not a calibrated probability of the final status.</div></div>`,'Native Laya option probabilities')}</div>`+
 `<div class="grid">${panel('Automation / accuracy trade-off',empty('Evidence before automation','Review held-out examples to measure how much work can safely be automated.','<a href="#review">Open review queue →</a>'),'No verified claim yet')}${panel('Local processing',`<div class="panel-body"><div class="definition-list"><dt>Primary model</dt><dd>Laya multilingual · 322M parameters</dd><dt>Model load</dt><dd>${b?num(Math.round(b.model_load_ms))+' ms':'Not measured yet'}</dd><dt>Row throughput</dt><dd>${b?Number(b.source_rows_per_second_this_session).toFixed(2)+' rows/sec (includes duplicate reuse)':'Baseline in progress'}</dd><dt>Inference throughput</dt><dd>${b?Number(b.unique_texts_per_second_this_session).toFixed(2)+' distinct texts/sec':'Not measured yet'}</dd><dt>Golden examples</dt><dd>${num(d.verified_total)} human-verified records</dd></div></div>`,'No notice text sent to an API')}</div>`+
 `<div class="demo-examples">${panel('Demonstration selections',`<div class="panel-body">${examples.map(r=>`<div class="demo-selection"><div><strong>${esc(r.title)}</strong><p>${esc(r.description)}</p><span class="sub">Public source · ${esc(r.source_file)} · unverified prediction</span></div><button data-record="${esc(r.id)}">Open notice</button></div>`).join('')}</div>`,'Real public excerpts · selected for illustration')}</div>`+panel('Recent classifications',rowTable(recent,true),'Open a record to inspect source and decision');
}
function filterSelect(key,label,options){return `<select aria-label="${label}" data-filter="${key}"><option value="">${label}</option>${options.map(v=>`<option value="${esc(v)}" ${state.filters[key]===v?'selected':''}>${esc(human(v))}</option>`).join('')}</select>`;}
async function explorer(queue=false){
 const params=new URLSearchParams({...state.filters,page:state.tablePage,page_size:40,...(queue?{queue:'true',cohort:'true'}:{}),...(state.run?{run_id:state.run}:{})});
 const data=await api(`notices?${params}`);
 const filters=`<div class="filters"><input type="search" id="search" aria-label="Search notices" placeholder="Search issuer, source ID or notice text…" value="${esc(state.filters.q||'')}">${filterSelect('classification','All classifications',statuses)}${filterSelect('review','All review states',['verified','unreviewed'])}${filterSelect('event_type','All document types',facets.event_type||[])}${filterSelect('country','All countries',facets.country||[])}${filterSelect('market','All markets',facets.market||[])}${filterSelect('language','All languages',facets.language||[])}${filterSelect('correct','All outcomes',['correct','incorrect'])}<select aria-label="Confidence range" id="confidence-filter"><option value="">All policy scores</option value="low" ${state.filters.max_confidence==='0.7'?'selected':''}>Below 70%</option><option value="high" ${state.filters.min_confidence==='0.98'?'selected':''}>At least 98%</option></select><button id="reset-filters">Reset</button></div>`;
 return heading(queue?'Human verification':'Source intelligence',queue?'Review queue':'Notice explorer',queue?'Prioritised by low score, conflicting factors, voting opportunity and restrictions. Every correction creates a new revision.':'Search the complete source corpus and inspect every decision.',exportLink())+
 (queue?notice('<strong>Reviewer responsibility.</strong> These public excerpts have no verified voting labels. Inspect the complete text before confirming. Test examples remain excluded from training.'):'')+
 `<section class="panel">${filters}${rowTable(data)}<div class="pagination"><span>${num(data.total)} matching records · Page ${state.tablePage} of ${Math.max(1,Math.ceil(data.total/40))}</span><div><button id="prev-page" ${state.tablePage<=1?'disabled':''}>← Previous</button><button id="next-page" ${state.tablePage*40>=data.total?'disabled':''}>Next →</button></div></div></section>`;
}
function automationChart(points){
 const p=points.filter(r=>r.auto_processed>0);
 if(!p.length)return empty('No eligible automation points','Verified examples with complete, non-conflicting decisions are needed.');
 const coords=(key)=>p.map(r=>`${40+r.threshold*540},${195-(r[key]??0)*160}`).join(' ');
 return `<div class="panel-body"><svg class="chart-svg" viewBox="0 0 620 235" role="img" aria-label="Confidence threshold versus auto coverage and accuracy"><path d="M40 25 V195 H590" fill="none" stroke="#cdd8df"/><path d="M40 115 H590 M40 35 H590" stroke="#e8edf1"/><text x="7" y="38">100%</text><text x="12" y="118">50%</text><text x="23" y="198">0</text><text x="40" y="217">0</text><text x="300" y="217">0.5</text><text x="570" y="217">1.0</text><polyline points="${coords('coverage')}" fill="none" stroke="#287f79" stroke-width="2"/><polyline points="${coords('accuracy')}" fill="none" stroke="#9aabbb" stroke-width="2"/></svg><div class="legend"><span>Auto coverage</span><span>Observed exact-decision accuracy</span></div><div class="chart-caption">Exploratory held-out curve. Policy selection must use validation data; test results cannot be used to choose thresholds.</div></div>`;
}
function experimentPanel(e){
 const rows=e.comparison.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.test?.n??'—'}</td><td>${pct(r.test?.all_field_exact_match_accuracy)}</td><td>${pct(r.test?.customer_status_accuracy)}</td><td>${r.test?.mean_field_macro_f1?.toFixed(3)??'—'}</td><td>${r.challenge_passed==null?'Not measured':r.challenge_passed+' / 57'}</td><td><button data-experiment-errors="${r.name==='Base Laya'?'base':'fine-tuned'}">Errors</button></td></tr>`).join('');
 const points=e.learning_curve.points||[];
 const curve=points.length?`<div class="table-wrap"><table><thead><tr><th>Training examples</th><th>Validation exact match</th><th>Mean factor macro F1</th><th>Votable recall</th><th>Restriction recall</th></tr></thead><tbody>${points.map(r=>`<tr><td>${r.n}</td><td>${pct(r.exact_match)}</td><td>${r.macro_f1?.toFixed(3)??'—'}</td><td>${pct(r.votable_recall)}</td><td>${pct(r.restriction_recall)}</td></tr>`).join('')}</tbody></table></div>`:empty('Learning curve not measured',e.learning_curve.message||'No result available.');
 return notice(`<strong>${esc(e.quality_gate.status)}</strong> · Automation disabled.<br>${e.quality_gate.reasons.map(esc).join('<br>')}`,true)+
 (e.challenge_risk?notice(`<strong>Semantic challenge: ${e.challenge_risk.fine_tuned_passed} / 57 pass.</strong> ${e.challenge_risk.regressed.length} regressions and ${e.challenge_risk.high_confidence_errors.length} errors with policy score ≥98%. The synthetic test does not establish safe automation.`,true):'')+
 panel('Supervised Laya experiment',`<div class="panel-body"><p>${esc(e.provenance)}</p><p>Public corpus review cohort: ${e.study.reviewed} / ${e.study.target} reviewed, ${e.study.expert_attested} expert-attested. This is separate from the supplied synthetic dataset.</p>${e.limitations.map(t=>`<p class="chart-caption">${esc(t)}</p>`).join('')}</div>`)+
 panel('Frozen synthetic test performance & semantic challenge set',`<div class="table-wrap"><table><thead><tr><th>Model</th><th>Synthetic test n</th><th>All-field exact match</th><th>Supplied customer status</th><th>Mean factor macro F1</th><th>Semantic challenge set</th><th>Inspect</th></tr></thead><tbody>${rows}</tbody></table></div>`,'AI-authored labels; supplied split contains duplicates')+
 panel('Learning Curve',(points.length?'<img src="/api/experiment/figure?name=learning-curve.svg" alt="Measured Laya decision-head validation learning curve" width="800">':'')+curve,'Validation only · never model-select on frozen test')+
 panel('Automation Coverage vs Accuracy',e.automation.models&&Object.keys(e.automation.models).length?`<div class="table-wrap"><table><thead><tr><th>Model</th><th>Threshold</th><th>Coverage</th><th>Exact-decision accuracy</th><th>Errors</th></tr></thead><tbody>${Object.entries(e.automation.models).flatMap(([name,rows])=>rows.map(r=>`<tr><td>${esc(human(name))}</td><td>${r.threshold.toFixed(2)}</td><td>${pct(r.coverage)}</td><td>${pct(r.accuracy)}</td><td>${r.wrong_auto_processed}</td></tr>`)).join('')}</tbody></table></div>`:empty('No measured synthetic automation curve','Automation stays disabled.'),'Synthetic diagnostic only; no customer automation claim');
}
async function syntheticErrorsView(){
 const params=new URLSearchParams({model:state.experimentModel,dataset:state.experimentDataset,field:state.experimentField,min_confidence:state.experimentMin,expected:state.experimentExpected,predicted:state.experimentPredicted});
 const data=await api(`experiment/errors?${params}`);
 return heading('Synthetic experiment','Fine-Tuned Model → Errors',state.experimentDataset==='challenge'?'Unchanged 57-case challenge. Expectations are partial assertions; unasserted fields are not truth.':'Supplied 100-case AI-authored test, with known duplicate overlap; no customer accuracy claim.')+
 `<div class="filters"><select id="experiment-dataset" aria-label="Evaluation corpus"><option value="challenge" ${state.experimentDataset==='challenge'?'selected':''}>Semantic challenge set (57)</option><option value="test" ${state.experimentDataset==='test'?'selected':''}>Supplied synthetic test (100)</option></select><select id="experiment-model" aria-label="Experiment model"><option value="fine-tuned" ${state.experimentModel==='fine-tuned'?'selected':''}>Fine-Tuned Laya</option><option value="base" ${state.experimentModel==='base'?'selected':''}>Base Laya</option></select><select id="experiment-field" aria-label="Failed factor"><option value="">All failed factors</option>${['votable','share_blocking','poa_required','other_restriction','deadline_status'].map(k=>`<option value="${k}" ${state.experimentField===k?'selected':''}>${esc(human(k))}</option>`).join('')}</select><select id="experiment-expected" aria-label="Expected synthetic result"><option value="">All expected results</option>${(state.experimentField?['YES','NO','UNCERTAIN','OPEN','PASSED','UNKNOWN']:statuses).map(k=>`<option value="${k}" ${state.experimentExpected===k?'selected':''}>${esc(human(k))}</option>`).join('')}</select><select id="experiment-predicted" aria-label="Predicted synthetic result"><option value="">All predicted results</option>${(state.experimentField?['YES','NO','UNCERTAIN','OPEN','PASSED','UNKNOWN']:statuses).map(k=>`<option value="${k}" ${state.experimentPredicted===k?'selected':''}>${esc(human(k))}</option>`).join('')}</select><button id="experiment-high">${state.experimentMin?'Show all':'High Confidence Wrong ≥98%'}</button><button id="public-errors">Public reviewed errors</button></div>`+
 panel(`${data.items.length} ${state.experimentDataset==='challenge'?'challenge':'synthetic test'} failures`,data.items.length?`<div class="panel-body">${data.items.map(r=>`<details><summary>${esc(r.id)} · ${esc(r.failed_fields.join(', ')||'customer status')} · ${pct(r.confidence)}</summary><p>${esc(r.text)}</p><div class="definition-list"><dt>Expected</dt><dd>${esc(JSON.stringify(r.expected))}</dd><dt>Predicted</dt><dd>${esc(JSON.stringify(r.observed))}</dd><dt>Customer status</dt><dd>${esc(r.expected_customer_status)} → ${esc(r.predicted_customer_status)}</dd></div>${Object.entries(r.scores).map(([k,v])=>`<strong>${esc(human(k))}</strong>${probabilityRows(v)}`).join('')}</details>`).join('')}</div>`:empty('No errors match this filter','Inspect sample support before interpreting an empty view.'));
}
async function performance(){
 const [m,runs,comparison]=await Promise.all([api(`performance?split=${state.split}&${runQuery()}`),api('runs'),api(`comparison?split=${state.split}`)]);
 const run=runs.find(r=>r.id===m.run_id);
 const tabs=`<div class="tabs">${['test','validation','all'].map(s=>`<button data-split="${s}" class="${state.split===s?'selected':''}">${s==='all'?'All reviewed (exploratory)':human(s)+' split'}</button>`).join('')}</div>`;
 const experiment=await api('experiment');
 const stages=await api(`metric-layers?${runQuery()}`);
 let html=layerMetricCards(stages)+await hybridSummaryPanel(true)+experimentPanel(experiment)+heading('Model evidence','How much work can AI safely remove?','Independent evaluation, operational coverage and the errors behind every metric.',exportLink('evaluation'))+tabs+
 notice(`<strong>${m.n?num(m.n)+' verified examples':'No verified examples'} in this view.</strong> ${state.split==='test'?'Test groups are held out of fine-tuning.':'Use validation only to select policies. All-reviewed metrics are exploratory.'} Scores below are supported only by human reviews.`)+
 `<div class="metrics">${metric('Derived-status agreement',pct(m.accuracy),`${num(m.n)} reviewed records`)}${metric('Macro F1',m.macro_f1==null?'—':m.macro_f1.toFixed(3),'Across all seven operational statuses')}${metric('Votable recall',pct(m.actionable_voting_recall),'Verified actionable votes recognised',true)}${metric('Independent source groups',num(m.unique_groups||0),'Group count matters more than row count')}</div>`;
 if(run) html+=panel('Current model',`<div class="panel-body"><div class="definition-list"><dt>Model</dt><dd>${esc(run.model)}</dd><dt>Checkpoint revision</dt><dd class="run-id">${esc(run.model_version)}</dd><dt>Run</dt><dd class="run-id">${esc(run.id)}</dd><dt>Reference date</dt><dd>${esc(run.config.evaluation_date)} (fixed)</dd><dt>Automation</dt><dd>Disabled · policy requires validation evidence</dd></div></div>`);
 html+=panel('Model comparison',`<div class="table-wrap"><table><thead><tr><th>Model / run</th><th>Verified n</th><th>Derived-status agreement</th><th>Macro F1</th><th>Auto coverage</th><th>Latency</th></tr></thead><tbody>${comparison.map(r=>`<tr><td>${esc(r.model)}<span class="sub">${esc(r.run_id.slice(0,8))} · ${esc(r.status)}</span></td><td>${r.verified_n}</td><td>${pct(r.accuracy)}</td><td>${r.macro_f1==null?'—':r.macro_f1.toFixed(3)}</td><td>${pct(r.auto_coverage)}</td><td>${r.median_latency_ms==null?'—':num(Math.round(r.median_latency_ms))+' ms/text'}</td></tr>`).join('')}</tbody></table></div>`,'Same selected reviewed split; inspect sample support');
 if(!m.n)return html+panel('Performance evidence',empty('Accuracy is not known yet','Confirm or correct notices in the review queue to build an independently verified dataset.','<a href="#review">Build the golden dataset →</a>'));
 html+=`<div class="grid equal">${panel('Automation curve',automationChart(m.curve),'Measured on selected reviewed split')}${panel('Operational outcomes',`<div class="panel-body"><div class="definition-list"><dt>Auto-processed</dt><dd>${num(m.auto_processed)}</dd><dt>Manual review</dt><dd>${num(m.manual_review)}</dd><dt>Wrong auto-processed</dt><dd>${num(m.wrong_auto_processed)}</dd><dt>All-factor exact match</dt><dd>${pct(m.all_factor_exact_match)}</dd><dt>Balanced accuracy</dt><dd>${pct(m.balanced_accuracy)}</dd><dt>Weighted F1</dt><dd>${m.weighted_f1.toFixed(3)}</dd><dt>Status score ECE</dt><dd>${m.status_score_ece.toFixed(3)} (diagnostic)</dd></div><p class="chart-caption">Current operational policy remains disabled. A 98% precision target requires sufficient validation support and a 95% Wilson lower confidence bound ≥98%.</p></div>`)}</div>`;
 html+=panel('Confusion matrix',`<div class="table-wrap"><table class="matrix"><thead><tr><th>True ↓ / AI →</th>${m.labels.map(s=>`<th>${esc(human(s))}</th>`).join('')}</tr></thead><tbody>${m.labels.map((s,i)=>`<tr><th>${esc(human(s))}</th>${m.confusion_matrix[i].map((n,j)=>`<td class="${i===j?'diagonal':''}"><button data-matrix-true="${esc(s)}" data-matrix-pred="${esc(m.labels[j])}" title="Inspect ${n} records">${n}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div>`,'Click a cell to inspect records');
 html+=panel('Precision, recall and F1 by category',`<div class="table-wrap"><table class="support-table"><thead><tr><th>Status</th><th>Precision</th><th>Recall</th><th>F1</th><th>Support</th></tr></thead><tbody>${m.labels.map(s=>{let r=m.per_category[s];return `<tr><td>${badge(s)}</td><td>${pct(r.precision)}</td><td>${pct(r.recall)}</td><td>${r['f1-score'].toFixed(3)}</td><td>${r.support}</td></tr>`;}).join('')}</tbody></table></div>`);
 html+=panel('Native factor calibration',`<div class="table-wrap"><table><thead><tr><th>Decision factor</th><th>Brier score ↓</th><th>Log loss ↓</th><th>ECE ↓</th></tr></thead><tbody>${Object.entries(m.factor_calibration).map(([k,v])=>`<tr><td>${esc(human(k))}</td><td>${v.brier.toFixed(4)}</td><td>${v.log_loss.toFixed(4)}</td><td>${v.ece.toFixed(4)}</td></tr>`).join('')}</tbody></table></div>`,'Native option distributions; no derived class probabilities');
 if(state.split==='validation')html+=notice(m.validation_policy_candidate?`Candidate threshold: <strong>${pct(m.validation_policy_candidate.threshold)}</strong>, observed coverage ${pct(m.validation_policy_candidate.coverage)}. Export for review before enabling a policy.`:'No threshold has sufficient validation support for the 98% precision target.',true);
 return html;
}
async function errors(){
 if(state.experimentErrors)return syntheticErrorsView();
 const m=await api(`performance?split=${state.split}&${runQuery()}`);
 const e=m.errors||{};
 let items=state.matrixFilter?(m.reviewed_examples||[]):(e.errors||[]);
 if(state.errorMode==='high')items=items.filter(r=>r.confidence>=.98);
 if(state.matrixFilter)items=items.filter(r=>r.true===state.matrixFilter.true&&r.predicted===state.matrixFilter.predicted);
 const grouped=(e.groups||{})[state.errorGroup]||[];
 return heading('Risk & investigation','Error analysis','Observed examples and repeated text patterns. No generated explanations for model errors.',exportLink('evaluation'))+
 `<div class="tabs"><button id="all-errors" class="${state.errorMode==='all'?'selected':''}">All errors (${(e.errors||[]).length})</button><button id="high-errors" class="${state.errorMode==='high'?'selected':''}">High confidence errors (${(e.high_confidence_errors||[]).length})</button><select id="error-group" aria-label="Group errors by">${['predicted','true','country','market','language','event_type','length_band','confidence_band'].map(k=>`<option value="${k}" ${state.errorGroup===k?'selected':''}>Group by ${esc(human(k))}</option>`).join('')}</select></div>`+
 (state.matrixFilter?notice(`Confusion cell: ${esc(human(state.matrixFilter.true))} → ${esc(human(state.matrixFilter.predicted))}. <button id="clear-matrix">Clear cell filter</button>`):'')+
 (!m.n?panel('Verified errors',empty('Errors need verified labels','Review examples before interpreting model performance.')):
 `<div class="grid equal">${panel('Errors by selected dimension',`<div class="table-wrap"><table><thead><tr><th>Group</th><th>Reviewed</th><th>Errors</th><th>Error rate</th></tr></thead><tbody>${grouped.map(g=>`<tr><td>${esc(human(g.value))}</td><td>${g.n}</td><td>${g.errors}</td><td>${pct(g.error_rate)}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Repeated phrases in errors',e.repeated_error_phrases?.length?`<div class="panel-body">${e.repeated_error_phrases.map(p=>`<div class="flag-row"><span>${esc(p.phrase)}</span><strong>${p.records} records</strong></div>`).join('')}<p class="chart-caption">Observed three-word phrases, counted once per error record. Repetition does not establish causation.</p></div>`:empty('No repeated pattern yet','More verified errors are needed.'))}</div>`+
 panel(state.matrixFilter?'Confusion cell examples':state.errorMode==='high'?'High confidence errors ≥98%':'Misclassified examples',items.length?`<div class="table-wrap"><table><thead><tr><th>Source record</th><th>Verified status</th><th>AI status</th><th>Policy score</th><th>Source type</th></tr></thead><tbody>${items.map(r=>`<tr class="clickable" data-record="${esc(r.id)}"><td>${esc(r.id)}</td><td>${badge(r.true)}</td><td>${badge(r.predicted)}</td><td>${pct(r.confidence)}</td><td>${esc(r.event_type)}</td></tr>`).join('')}</tbody></table></div>`:empty('No errors in this view','This may reflect limited review support; inspect sample counts.')));
}
async function runsPage(){
 const runs=await api('runs');
 return heading('Reproducibility','Model runs & audit','Immutable predictions. Versioned configurations. Every source row accounted for.',`<button class="primary" id="start-run">Run Laya baseline</button>${exportLink('audit')}`)+
 notice('<strong>Local execution.</strong> Batch jobs use the installed Laya checkpoint. Reproduce creates a new run with the same inputs and configuration; historical predictions remain unchanged.')+
 panel('Experiment ledger',runs.length?`<div class="table-wrap"><table><thead><tr><th>Run / Checkpoint</th><th>Started</th><th>State</th><th>Outputs</th><th>Speed</th><th>Actions</th></tr></thead><tbody>${runs.map(r=>`<tr><td><span class="run-id">${esc(r.id)}</span><span class="sub">${esc(r.model)} · ${esc(r.model_version.slice(0,10))}</span></td><td>${esc(new Date(r.created_at).toLocaleString('en-GB'))}</td><td>${esc(r.status)}</td><td>${num(r.persisted)} / ${num(r.manifest.inputs)}</td><td>${r.benchmark?Number(r.benchmark.unique_texts_per_second_this_session).toFixed(2)+' texts/s':'In progress'}</td><td><button data-select-run="${esc(r.id)}">Inspect</button> <button data-reproduce="${esc(r.id)}" ${r.config.option_order?'':'disabled title="Legacy run predates explicit option order"'}>Reproduce</button></td></tr>`).join('')}</tbody></table></div>`:empty('No experiments yet','Download the model, import data and run the baseline.'))+
 runs.filter(r=>r.benchmark).map(r=>panel(`Measured benchmark · ${r.id.slice(0,8)}`,`<div class="panel-body"><div class="definition-list">${Object.entries(r.benchmark).map(([k,v])=>`<dt>${esc(human(k))}</dt><dd>${esc(typeof v==='number'?num(Number(v.toFixed(3))):v)}</dd>`).join('')}</div><h3>Reproduction manifest</h3><div class="definition-list"><dt>Configuration hash</dt><dd class="run-id">${esc(r.config_version)}</dd><dt>Dataset hash</dt><dd class="run-id">${esc(r.dataset_hash)}</dd><dt>Source fingerprint</dt><dd class="run-id">${esc(r.manifest.source_fingerprint)}</dd></div></div>`)).join('');
}
async function dataset(){
 const [p,revisions]=await Promise.all([api('profile'),api('dataset-revisions')]);
 return heading('Scientific scope','Dataset & methodology','Know exactly what this experiment measures, and where the evidence ends.',`<a class="button" href="/api/profile" target="_blank" rel="noopener">View full profile</a>`)+
 notice('<strong>Scope change.</strong> No 15,022-record customer corpus was supplied. This workspace uses a sourced public example corpus. It must not be presented as customer data or a representative global notice benchmark.',true)+
 `<div class="metrics">${metric('Source rows',num(p.records),'Unmodified downloaded source files')}${metric('Distinct normalised texts',num(p.unique_texts),'Reuse disclosed in performance figures')}${metric('Duplicate / filing groups',num(p.duplicate_groups),'Groups allocated to one split only')}${metric('Verified voting labels','None in source','Human review builds the golden dataset')}</div>`+
 panel('Source & provenance',`<div class="panel-body wide-notes"><p><a href="${esc(p.source)}" target="_blank" rel="noopener">TheTokenFactory / SEC financial extraction instructions</a> · CC BY 4.0. The publisher describes excerpts from SEC contracts and proxy statements, drawn from S&P 500 companies. We preserve raw downloads and select only the <code>input</code> field for Laya.</p><p>The publisher used a generative model to create extraction targets. Those targets, extraction instructions and extraction confidence values are excluded from inference and golden labels. The application sends no notice text to an external model.</p><div class="definition-list"><dt>Source revision</dt><dd class="run-id">${esc(p.revision)}</dd><dt>Unit of observation</dt><dd>${esc(p.unit)}</dd><dt>Document types</dt><dd>${esc(JSON.stringify(p.document_types))}</dd><dt>Country / market / ISIN</dt><dd>Unknown or not supplied; SEC filing does not establish issuer domicile.</dd><dt>Language</dt><dd>Heuristic only. Short tables can produce false non-English detections.</dd><dt>Source labels</dt><dd>No verified votability labels.</dd></div></div>`)+
 (revisions.length?panel('Dataset revision history',`<div class="panel-body wide-notes">${revisions.map(r=>`<p><strong>${esc(r.id)}</strong> · ${esc(new Date(r.created_at).toLocaleString('en-GB'))}</p><p>Corrected ${num(r.metadata.changed_split_rows)} split assignments before human labelling. All original notice text, hashes, model inputs and prediction bytes were preserved. The original database is retained for audit.</p>`).join('')}</div>`):'')+panel('Factorised taxonomy',`<div class="panel-body wide-notes"><p>A vote may require both a POA and share blocking. We therefore keep voting opportunity, three independent restriction factors and deadline state separate. The public corpus cannot establish that the original seven statuses are mutually exclusive; this remains a provisional schema.</p><div class="definition-list"><dt>Votability</dt><dd>YES / NO / UNCERTAIN</dd><dt>Restrictions</dt><dd>Share blocking, POA and other restriction · yes / no / unknown</dd><dt>Deadline</dt><dd>OPEN / PASSED / UNKNOWN, relative to a fixed reference date</dd><dt>Derived status</dt><dd>Uncertain → Not votable → Passed deadline → Multiple/other restrictions → POA → Blocking → Votable</dd><dt>Unknown deadline</dt><dd>A votable notice with an unknown deadline always requires review.</dd><dt>Confidence</dt><dd>Native probabilities per factor. The minimum winning probability is a conservative policy score, not a joint status probability.</dd></div></div>`)+
 panel('Golden dataset → independent evidence',`<div class="panel-body"><div class="workflow"><span>Source notice</span><b>→</b><span>Laya prediction</span><b>→</b><span>Human revision</span><b>→</b><span>Golden label</span><b>→</b><span>Group-separated training</span><b>→</b><span>Held-out evaluation</span></div><p class="wide-notes">Exact and near duplicates, plus all excerpts from a common filing, share a split. Train / validation / test assignment is deterministic from group hashes (60 / 20 / 20 expected). Labels cannot move records into another split. Corpus imports freeze after the first review. An exact prefix-filter Jaccard join checks all pairs at the configured similarity threshold. Semantic paraphrases below that threshold still need audit.</p><p class="wide-notes">The primary model is the official Laya multilingual checkpoint, using the native SDK and five choice questions. Truncated inputs are disclosed and escalated. Full source text always remains visible. Automation is off until validation establishes a useful threshold.</p></div>`)+
 panel('What this PoC proves — and what it does not',`<div class="panel-body wide-notes"><p>This workspace can measure a specialised model's decisions, preserve their provenance, collect reviewer corrections, prevent known group leakage and compare experiments.</p><p>A completed batch does not prove classification quality. Synthetic fixtures are regression specifications, not independent customer evidence. Small-sample accuracy cannot establish safe operation, and public filing excerpts do not represent every market, language, custodian rule or shareholder eligibility condition.</p></div>`);
}
async function render(){
 const generation=++renderGeneration;
 state.page=location.hash.slice(1)||'overview';
 const names={confidence:'Confidence & Automation',model_lab:'Model Lab',overview:'Overview',explorer:'Notice explorer',review:'Review queue',performance:'Model performance',errors:'Error analysis',runs:'Model runs & audit',dataset:'Dataset & methodology'};
 if(!names[state.page]){location.hash='overview';return;}
 $$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===state.page));
 $('#breadcrumb').textContent=`Workspace / ${names[state.page]}${state.run?' / Run '+state.run.slice(0,8):''}`;
 try{
 const views={confidence:domainConfidencePage,model_lab:modelLab,overview,explorer:()=>explorer(false),review:()=>explorer(true),performance,errors,runs:runsPage,dataset};
 const html=await views[state.page]();
 if(generation!==renderGeneration)return;
 $('#content').innerHTML=html;bars();bindRows();bindPage();
 }catch(e){if(generation===renderGeneration){$('#content').innerHTML=`<div class="error-banner">${esc(e.message)} <button id="retry">Retry</button></div>`;$('#retry').onclick=render;}}
}
