 $('#search')?.addEventListener('input',e=>{state.filters.q=e.target.value;state.tablePage=1;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(async()=>{const pos=e.target.selectionStart;await render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);},350);});
 $$('[data-filter]').forEach(el=>el.addEventListener('change',()=>{state.filters[el.dataset.filter]=el.value;state.tablePage=1;render();}));
 $('#confidence-filter')?.addEventListener('change',e=>{delete state.filters.max_confidence;delete state.filters.min_confidence;if(e.target.value==='low')state.filters.max_confidence='0.7';if(e.target.value==='high')state.filters.min_confidence='0.98';state.tablePage=1;render();});
 $('#reset-filters')?.addEventListener('click',()=>{state.filters={};state.tablePage=1;render();});
