 $$('[data-experiment-errors]').forEach(el=>el.addEventListener('click',()=>{state.experimentErrors=true;state.experimentModel=el.dataset.experimentErrors;location.hash='errors';}));
 $('#experiment-dataset')?.addEventListener('change',e=>{state.experimentDataset=e.target.value;state.experimentExpected='';state.experimentPredicted='';render();});
 $('#experiment-model')?.addEventListener('change',e=>{state.experimentModel=e.target.value;render();});
 $('#experiment-field')?.addEventListener('change',e=>{state.experimentField=e.target.value;state.experimentExpected='';state.experimentPredicted='';render();});
 $('#experiment-expected')?.addEventListener('change',e=>{state.experimentExpected=e.target.value;render();});
 $('#experiment-predicted')?.addEventListener('change',e=>{state.experimentPredicted=e.target.value;render();});
 $('#experiment-high')?.addEventListener('click',()=>{state.experimentMin=state.experimentMin?0:.98;render();});
 $('#public-errors')?.addEventListener('click',()=>{state.experimentErrors=false;render();});
 $('#all-errors')?.addEventListener('click',()=>{state.errorMode='all';render();});$('#high-errors')?.addEventListener('click',()=>{state.errorMode='high';render();});
 $('#error-group')?.addEventListener('change',e=>{state.errorGroup=e.target.value;render();});
 $('#clear-matrix')?.addEventListener('click',()=>{state.matrixFilter=null;render();});
 $$('[data-matrix-true]').forEach(el=>el.addEventListener('click',()=>{state.matrixFilter={true:el.dataset.matrixTrue,predicted:el.dataset.matrixPred};state.errorMode='all';location.hash='errors';}));
 $('#start-run')?.addEventListener('click',()=>startRun({}));
 $$('[data-reproduce]').forEach(el=>el.addEventListener('click',()=>startRun({reproduce:el.dataset.reproduce})));
