function select(name,value,options,label){return `<label>${esc(label)}<select name="${name}" aria-label="${esc(label)}">${options.map(v=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(human(v))}</option>`).join('')}</select></label>`;}
function evidenceAnchor(ref,index){
 const target=ref.kind==='model'?`evidence-factor-${ref.factor}`:ref.kind==='metadata'?`evidence-metadata-${ref.key}`:ref.kind==='deadline'?'evidence-deadline':ref.kind==='usage'?'evidence-usage':'source-evidence-highlight';
 return `<a href="#${esc(target)}" data-evidence-index="${index}" class="evidence-link">${esc(ref.label)}</a>`;
}
function bindEvidence(d){
 $$('[data-evidence-link="source"]').forEach(a=>a.addEventListener('click',event=>{
  event.preventDefault();const chars=Array.from(d.text),start=Number(a.dataset.start),end=Number(a.dataset.end);
  if(!Number.isInteger(start)||!Number.isInteger(end)||start<0||end>chars.length||end<=start)return;
  $('.source-text').innerHTML=esc(chars.slice(0,start).join(''))+`<mark id="source-evidence-highlight" tabindex="-1">${esc(chars.slice(start,end).join(''))}</mark>`+esc(chars.slice(end).join(''));
  const target=$('#source-evidence-highlight');target.scrollIntoView({block:'center'});target.focus({preventScroll:true});
 }));
 const refs=(d.decision_evidence||[]).flatMap(e=>e.links||[]);
 $$('[data-evidence-index]').forEach(a=>a.addEventListener('click',event=>{
  event.preventDefault();const ref=refs[Number(a.dataset.evidenceIndex)];let target;
  if(ref.kind==='source'){
   const chars=Array.from(d.text);const start=ref.start,end=ref.end;
   if(ref.offset_unit!=='unicode_codepoints'||!Number.isInteger(start)||!Number.isInteger(end)||start<0||end>chars.length||end<=start)return;
   $('.source-text').innerHTML=esc(chars.slice(0,start).join(''))+`<mark id="source-evidence-highlight" tabindex="-1">${esc(chars.slice(start,end).join(''))}</mark>`+esc(chars.slice(end).join(''));
   target=$('#source-evidence-highlight');
  }else{
   const id=ref.kind==='model'?`evidence-factor-${ref.factor}`:ref.kind==='metadata'?`evidence-metadata-${ref.key}`:ref.kind==='deadline'?'evidence-deadline':'evidence-usage';
   target=document.getElementById(id);
  }
  if(!target)return;
  for(let parent=target;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
  target.scrollIntoView({block:'center'});target.focus({preventScroll:true});
 }));
}
function whyEvidence(d){
 let index=0;
 return `<section class="decision-evidence" aria-label="Decision evidence"><h3>Why?</h3><ul>${d.decision_evidence.map(e=>`<li>${esc(e.message)}${e.quote?`<blockquote>${esc(e.quote)}</blockquote>`:''}<span class="sub">${esc(e.basis)}</span><div>${(e.links||[]).map(ref=>evidenceAnchor(ref,index++)).join(' · ')}</div></li>`).join('')}</ul></section>`;
}
async function openNotice(id){
 try{
 const d=await api(`notice?id=${encodeURIComponent(id)}&blind=${state.page==='review'}&${runQuery()}`);state.detail=d;
 const ai=d.prediction,m=d.metadata;
 const label=d.review?.action==='VERIFY'?d.review.label:ai?.decision;
 const dec=label||{votable:'UNCERTAIN',share_blocking:null,poa_required:null,other_restriction:null,deadline_status:'UNKNOWN'};
 const flagValue=v=>v===true?'YES':v===false?'NO':'UNKNOWN';
 $('#notice-content').innerHTML=`<div class="detail-header"><p class="eyebrow">Source notice · ${esc(d.split)} split</p><h2 id="notice-title">${esc(m.issuer)}</h2><div class="detail-meta"><span>${esc(m.event_type)}</span><span>Reference date: ${esc(d.evaluation_date)}</span><span>Market: ${esc(m.market)}</span><span>Language: ${esc(m.language)} (heuristic)</span><span>${d.review?.action==='VERIFY'?'Verified golden label':'Awaiting human verification'}</span></div></div><div class="detail-grid"><section class="source-side"><h3>Original notice · complete source</h3><div class="source-text" tabindex="0">${esc(d.text)}</div><div class="provenance">Source: <a href="${esc(m.source_url)}" target="_blank" rel="noopener">Public SEC excerpt · source row ${esc(m.source_row)}</a><br>Source file: ${esc(m.source_file)}<br>Original text is preserved. This excerpt is not a complete filing.<details id="evidence-source-metadata"><summary>Source metadata</summary><dl>${Object.entries(m).map(([k,v])=>`<dt>${esc(k)}</dt><dd id="evidence-metadata-${esc(k)}" tabindex="-1">${esc(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl></details><div class="technical">SHA-256: ${esc(d.source_hash)}<br>Group: ${esc(d.group_id)}<br>Record: ${esc(d.id)}</div></div></section><section class="decision-side">${ai?`<p class="eyebrow">Laya decision · unverified${d.review?.action==='VERIFY'?' (reviewed)':''}</p><div class="decision-title">${esc(human(ai.classification))}</div><div class="decision-score">${pct(ai.confidence)}</div><div class="score-description">Decision policy score<br>${esc(ai.confidence_definition)}</div><span class="badge">${esc(human(ai.action))}</span><div class="decision-flags">${[['Voting opportunity',ai.decision.votable],['Share blocking',flagValue(ai.decision.share_blocking)],['Power of attorney',flagValue(ai.decision.poa_required)],['Other restriction',flagValue(ai.decision.other_restriction)],['Deadline',ai.decision.deadline_status]].map(([k,v])=>`<div class="flag-row"><span>${esc(k)}</span><strong>${esc(human(v))}</strong></div>`).join('')}</div>${d.decision_evidence?.length?whyEvidence(d):''}${d.hybrid_inspection?hybridInspection(d.hybrid_inspection):''}${ai.review_reasons.length?`<div class="review-reasons">${ai.review_reasons.map(esc).join('<br>')}</div>`:''}<details><summary><h3>Native model scores by factor</h3></summary>${Object.entries(ai.scores).map(([k,s])=>`<div class="score-group" id="evidence-factor-${esc(k)}" tabindex="-1"><strong>${esc(human(k))}</strong><p>${esc(d.decision_configuration?.questions?.[k]?.instructions||'')}</p>${probabilityRows(s)}</div>`).join('')}</details>${ai.deadline_evidence?`<details id="evidence-deadline" tabindex="-1"><summary>Deadline comparison evidence</summary><pre>${esc(JSON.stringify(ai.deadline_evidence,null,2))}</pre></details>`:''}<div class="technical" id="evidence-usage" tabindex="-1">Model: ${esc(ai.model_name)}<br>Revision: ${esc(ai.model_version)}<br>SDK: ${esc(ai.sdk_version)}<br>Amortised inference: ${num(Math.round(ai.processing_time_ms))} ms/text${ai.cache_hit?' · duplicate reuse':''}<br>Run: ${esc(d.run_id)}<br>Config: ${esc(ai.configuration_version)}<br>Context truncated: ${ai.usage.truncated?'Yes — requires review':'No'}</div>`:d.blind_review?empty('Blind expert review','AI predictions are hidden. Review the full source and label each factor.'):d.classification_error?empty('Classification failed','This source row was retained without a prediction. Inspect the run ledger and rerun in a new experiment.'):empty('Awaiting model prediction','Run the local baseline to see Laya’s decision.')}${!d.blind_review?noticeSemanticTrace(d):''}${!d.blind_review?domainNoticeConfidence(d):''}${!d.blind_review?fastNoticeTrace(d):''}${!d.blind_review&&d.framework_execution?frameworkExecutionTrace(d.framework_execution):''}${domainReviewForm(d)}<h3>Legacy five-factor verification</h3><form id="review-form"><div class="form-grid">${select('votable',dec.votable,['YES','NO','UNCERTAIN'],'Verified voting opportunity')}${select('deadline_status',dec.deadline_status,['OPEN','PASSED','UNKNOWN'],'Verified deadline status')}${select('share_blocking',flagValue(dec.share_blocking),['YES','NO','UNKNOWN'],'Share blocking')}${select('poa_required',flagValue(dec.poa_required),['YES','NO','UNKNOWN'],'POA required')}${select('other_restriction',flagValue(dec.other_restriction),['YES','NO','UNKNOWN'],'Other restriction')}<label>Reviewer<input name="reviewer" aria-label="Reviewer" required maxlength="120" placeholder="Your name" value="${esc(localStorage.getItem('reviewer')||'')}"></label><label class="full"><span><input type="checkbox" name="domain_expert_attested" value="yes"> I have relevant domain expertise and have verified this label from the source.</span></label><label class="full">Reviewer notes<textarea name="notes" aria-label="Reviewer notes" maxlength="10000" placeholder="Evidence, interpretation or reason for correction"></textarea></label></div><div class="review-actions"><button class="primary" type="submit" id="confirm-review">${d.review?.action==='VERIFY'?'Save new revision':'Confirm / correct'}</button><button type="button" id="flag-review">Flag for review</button><button type="button" id="save-next">Save & next</button></div><p class="chart-caption">Change factors to correct the prediction. Status is derived automatically. Every save retains previous revisions. ${d.split==='test'?'This example stays in the test split and is excluded from training.':''}</p></form>${d.history.length?`<h3>Revision history</h3>${d.history.map(r=>`<div class="history-item"><strong>Revision ${r.id} · ${esc(r.reviewer)} · ${esc(r.action)}</strong><br>${esc(new Date(r.reviewed_at).toLocaleString('en-GB'))}<br>${esc(r.notes)}</div>`).join('')}`:''}</section></div>`;
 bars();bindEvidence(d);bindDomainReview(d);$('#review-form').addEventListener('submit',e=>{e.preventDefault();saveReview('VERIFY');});$('#flag-review').addEventListener('click',()=>saveReview('FLAG'));$('#save-next').addEventListener('click',()=>saveReview('VERIFY',true));$('#review-form').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();saveReview('VERIFY',true);}});
 if(!$('#notice-dialog').open)$('#notice-dialog').showModal();
 }catch(e){toast(e.message);}
}
async function saveReview(action,next=false){
 const form=$('#review-form');if(!form.reportValidity())return;
 const values=Object.fromEntries(new FormData(form));
 const bool=v=>v==='YES'?true:v==='NO'?false:null;
 const d=state.detail;
 const body={record_id:d.id,run_id:d.run_id,reviewer:values.reviewer,notes:values.notes,action,domain_expert_attested:values.domain_expert_attested==='yes',blind_review:!!d.blind_review,expected_revision:d.review?.id??null,
 decision:action==='VERIFY'?{votable:values.votable,deadline_status:values.deadline_status,share_blocking:bool(values.share_blocking),poa_required:bool(values.poa_required),other_restriction:bool(values.other_restriction),manual_review_required:false}:null};
 try{await api('reviews',{method:'POST',body:JSON.stringify(body)});localStorage.setItem('reviewer',values.reviewer);toast(action==='VERIFY'?'Golden label saved. Review history retained.':'Notice flagged for review.');if(next){const queue=await api(`notices?queue=true&cohort=true&page_size=1&${runQuery()}`);if(queue.items.length)await openNotice(queue.items[0].id);else{$('#notice-dialog').close();toast('Review queue complete.');}}else await openNotice(d.id);await render();}catch(e){toast(e.message);}
}
