async function hybridSummaryPanel(full){
 const h=await api('hybrid/summary');const p=h.public_parser;
 if(!p)return '';
 let html=panel('Input structure · public corpus',`<div class="panel-body"><div class="definition-list">${['VALID_ISO15022','PARTIAL_ISO15022','ISO15022_LIKE','UNSTRUCTURED_NOTICE','UNRECOGNISED'].map(k=>`<dt>${esc(human(k))}</dt><dd>${num(p.counts[k]||0)}</dd>`).join('')}<dt>Structured values extracted</dt><dd>${num(p.structured_values)}</dd><dt>Laya executions in this parser audit</dt><dd>${num(p.laya_executions)}</dd><dt>LLM escalations</dt><dd>${num(p.llm_escalations)}</dd><dt>Decision facts resolved by deterministic output</dt><dd>${h.routing?num(h.routing.deterministic_nonunknown_fact_outputs)+' / '+num(h.routing.total_decision_fact_slots):'Not measured'}</dd><dt>Planned narrow-Laya predicate slots</dt><dd>${h.routing?num(h.routing.planned_laya_predicate_slots)+' (not executed in this audit)':'Not measured'}</dd><dt>Human-review policy cases</dt><dd>${h.routing?num(h.routing.human_review_cases):'Not measured'}</dd></div><p>VALID requires full conformance validation, which this subset parser does not provide. Partial messages retain unsupported fields. ${esc(h.metrics_scope)}</p></div>`,'Measured detection; never reinterpret filings as SWIFT messages');
 if(!full)return html;
 const rows=[['Legacy whole-text Laya',30,57],['Parser + narrow base Laya',h.base?.passed,h.base?.cases],['Parser + narrow fine-tuned Laya',h.fine_tuned?.passed,h.fine_tuned?.cases]];
 html+=panel('Hybrid architecture experiment',`<div class="table-wrap"><table><thead><tr><th>Architecture</th><th>Cases satisfying supplied partial assertions</th><th>Customer accuracy</th></tr></thead><tbody>${rows.map(([label,n,total])=>`<tr><td>${esc(label)}</td><td>${n==null?'Not measured':n+' / '+total}</td><td>Not established</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p>These 57 authored notices have no ISO15022 structure. This comparison tests semantic formulation, chunk aggregation and policy together; it cannot establish parsing benefit. Automation remains disabled.</p><p>Exact parser reference checks: ${h.parser_verification?num(h.parser_verification.exact_assertions_passed)+' / '+num(h.parser_verification.exact_assertions_total):'Not measured'} (generated partial fixtures and official excerpt; not production accuracy).</p><p>Corpus provenance: ${Object.entries(h.corpus_provenance_counts).map(([k,v])=>`${esc(human(k))}: ${num(v)}`).join(' · ')}. Generated fixtures include malformed inputs.</p>${h.event_demo_available?'<button id="inspect-event-history">Inspect synthetic event history</button>':''}${h.available_examples.map(id=>`<button data-hybrid-example="${esc(id)}">Inspect ${esc(id)}</button>`).join(' ')}<p><button data-hybrid-errors="base">Base narrow Laya → Errors</button> <button data-hybrid-errors="fine">Fine-tuned narrow Laya → Errors</button></p><p><a href="/api/hybrid/summary" target="_blank" rel="noopener">View exact experiment denominators and native predicate metrics</a></p></div>`,'Historical parser + narrow-Laya only; no LLM. Parser assertions, model predicates and final policy stay separate');
 return html;
}
function hybridInspection(h){
 return `<details class="hybrid-inspection"><summary>Standards-aware pipeline · ${esc(h.parsed.kind)}</summary><p>Parser: ${esc(h.parsed.version)} · ${esc(h.parsed.message_type||'No message type established')}. This is an experimental subset reader, not a FIN conformance validator.</p><h4>Parsed structure and source fields</h4>${h.parsed.facts.filter(f=>f.name!=='sequence').map(f=>`<p>${esc(human(f.name))}: ${esc(typeof f.value==='object'?JSON.stringify(f.value):f.value)} <a href="#" class="evidence-link" data-evidence-link="source" data-start="${f.start}" data-end="${f.end}">Original ${esc(f.field_id)}</a></p>`).join('')||'<p>No supported ISO15022 facts found.</p>'}<h4>Semantic analysis</h4>${Object.entries(h.semantic_analysis.predicates||{}).map(([k,a])=>`<p><strong>${esc(human(k))}</strong>: ${esc(a.value)} · ${a.confidence==null?'Abstained':pct(a.confidence)+' native passage score'}${a.evidence?`<br><a href="#" class="evidence-link" data-evidence-link="source" data-start="${a.evidence.start}" data-end="${a.evidence.end}">“${esc(a.evidence.text)}”</a><br><span class="sub">Source-exact Laya candidate; not a verified explanation.</span>`:'<br>Evidence span unavailable'}</p><details><summary>Native passage scores</summary><pre>${esc(JSON.stringify(a.scores,null,2))}</pre></details>`).join('')||'<p>Narrow Laya not executed for this inspection. Existing whole-text results remain a separate benchmark.</p>'}<h4>Rules and final decision</h4><p>${esc(human(h.decision.classification))}<br>${esc(h.decision.rule)}<br>Deadline: ${esc(h.deadline.status)} · automation disabled</p><details><summary>Deadline calculation and evidence</summary><pre>${esc(JSON.stringify(h.deadline,null,2))}</pre></details><details><summary>Field routing trace · unknown fields preserved</summary><pre>${esc(JSON.stringify(h.routing_trace,null,2))}</pre></details></details>`;
}
