 if(!d.summary)body+=`<div class="table-wrap"><table><thead><tr><th>Stage</th>${['D1','D2','D3','C1','C2','C3'].map(a=>`<th>${a}</th>`).join('')}</tr></thead><tbody>${Object.entries(d.progress).map(([name,arms])=>`<tr><td>${esc(name)} · persisted rows</td>${['D1','D2','D3','C1','C2','C3'].map(a=>`<td>${arms[a]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="panel-body">No incomplete model comparison is presented as a result. D1/C1 = GLM; D2/C2 = Qwen Direct; D3/C3 = Qwen Thinking.</p>`;
