 form.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form));const label=Object.fromEntries(domainReviewKeys.map(k=>[k,v[k]]));try{const result=await api('domain/reviews',{method:'POST',body:JSON.stringify({record_id:d.id,expected_revision:revision,reviewer:v.reviewer,label,notes:v.notes,domain_expert_attested:!!v.domain_expert_attested,blind_review:!!d.blind_review,evaluation_time:v.evaluation_time,label_origin:v.label_origin,reviewer_model:v.reviewer_model||null,evidence:JSON.parse(v.semantic_evidence||'{}'),deadline_mentioned:!!v.deadline_mentioned,deadline_text:v.deadline_text||null})});revision=result.revision;localStorage.setItem('reviewer',v.reviewer);$('#domain-review-revision').textContent=`Revision ${revision} saved · ${human(result.classification)} · ${result.training_eligible?'train partition':'excluded from training'}`;toast('Complete predicate review saved. Prior revisions retained.');}catch(error){toast(error.message);}};
