function fastCascadeTrace(row){
 if(!row)return '<p>No cascade execution saved. Opening this view does not invoke a model.</p>';
 const r=row.result, preds=r.predicates||{}, confidence=r.confidence||{};
 const gear=(title,stage)=>`<h4>${esc(title)}</h4>${stage?Object.entries(stage.predicates||{}).map(([k,p])=>`<p>${esc(human(k))}: <strong>${esc(p.value)}</strong>${p.raw_model_probability?`<br>Raw model probability (not calibrated): ${pct(Math.max(...Object.values(p.raw_model_probability)))}`:p.confidence!=null?`<br>Native Laya score (not calibrated): ${pct(p.confidence)}`:''}</p>`).join(''):'<p>NOT INVOKED</p>'}`;
 return `<p>Execution ${esc(row.id||r.model_identity)} · input ${esc(r.input_type)}<br>Parser: ${esc(r.parser?.parser||'NOT APPLICABLE')}<br>Automation DISABLED · actual manual review REQUIRED</p>${gear('Gear 1 · Laya',r.laya)}<h4>Escalation reasons</h4><pre>${esc(JSON.stringify(r.escalation,null,2))}</pre>${gear('Gear 2 · Constrained Qwen',r.gear2)}<h4>Gear 3 · Full Qwen Direct</h4><p>${r.full_qwen?`${esc(r.full_qwen.model)} · ${esc(r.full_qwen.prompt_version)} · ${r.full_qwen.valid?'VALID SCHEMA':'FAILED SCHEMA'}`:'NOT INVOKED'}</p><h4>Reconciled predicates</h4>${Object.entries(preds).map(([k,p])=>{const c=confidence[k]||{};return `<p><strong>${esc(human(k))}: ${esc(p.value)}</strong><br>Source: ${esc(r.predicate_origins?.[k]||p.source)}<br>${c.confidence==null?`HEURISTIC / NOT YET CALIBRATED · ${esc(c.heuristic_band||'UNRESOLVED')}`:`Calibrated on synthetic population only: ${pct(c.confidence)}`}${(p.evidence||[]).filter(e=>e.valid).map(e=>`<br><a href="#" data-evidence-link="source" data-start="${e.start}" data-end="${e.end}">“${esc(e.text)}”</a>`).join('')||'<br>Evidence span unavailable'}</p>`;}).join('')}<h4>Final status</h4><p>${esc(human(r.decision.classification))}<br>Semantic review: ${r.semantic_review_required?'REQUIRED':'Resolved in experiment; human review still mandatory'}<br>${esc((r.reconciliation?.conflicts||[]).join(' · '))}</p><details><summary>Persisted reconciliation and identity</summary><pre>${esc(JSON.stringify({model_identity:r.model_identity,policy:r.policy,reconciliation:r.reconciliation,decision_confidence:r.decision_confidence,latency_ms:r.latency_ms,latency_scope:r.latency_scope},null,2))}</pre></details>`;
}
