async function fastCascadePanel(){
 const d=await api('fast-cascade/status'),p=d.selection?.policies||[];
 const ops=Object.entries(d.throughput||{}).filter(([k,v])=>v).map(([k,v])=>`<p>${k} actual notices · ${num(v.notices_per_hour?.toFixed(1))}/hour · mean elapsed ${num((v.total_measured_active_seconds*1000/v.n).toFixed(0))} ms · p95 service ${num(v.p95_service_latency_ms?.toFixed(0))} ms<br>Laya-only ${num(v.laya_only_notice_count)}; constrained ${num(v.constrained_notice_calls)} · full requests ${num(v.full_qwen_calls)} (actual inference ${num(v.actual_full_qwen_model_invocations)}) · semantically unresolved ${num(v.semantic_review_count)}<br>Any-Qwen request avoidance ${pct(1-v.any_qwen_notice_calls/v.n)} · Full-Qwen inference avoidance ${pct(1-v.actual_full_qwen_model_invocations/v.n)}</p>`).join('');
 return panel('Laya-first cascade · measured experiment',`<div class="panel-body"><p><strong>${esc(d.state?.state||'PREPARING')}</strong> · ${esc(d.state?.stage||'Awaiting measurements')}<br>Selection: ${esc(d.selection?.status||'Pending validation')}<br>Customer accuracy UNKNOWN · AUTOMATION DISABLED</p><p>Raw scores and token probabilities are not calibrated confidence. Unsupported calibration remains unavailable.</p>${ops||'<p>Actual 100/1,000-notice throughput is pending.</p>'}</div>${p.length?`<div class="table-wrap"><table><thead><tr><th>Validation policy</th><th>Correct / assertions</th><th>Gear 2 calls</th><th>Full Qwen calls</th><th>Semantic review</th></tr></thead><tbody>${p.map(v=>`<tr><td>${esc(v.policy.name)}</td><td>${v.metrics.correct_assertions}/${v.metrics.assertions}</td><td>${pct(v.metrics.gear2_notice_rate)}</td><td>${pct(v.metrics.gear3_notice_rate)}</td><td>${pct(v.metrics.semantic_review_rate)}</td></tr>`).join('')}</tbody></table></div><div class="panel-body"><p>Policy comparison is replayed from measured components; actual throughput is displayed separately.</p></div>`:''}<div class="panel-body"><button id="fast-load-cases">Inspect saved cascade comparisons</button><div id="fast-case-selector"></div><div id="fast-case-comparison"></div></div>`);
}
document.addEventListener('click',async e=>{
 if(e.target.id!=='fast-load-cases')return;
 try{const d=await api('fast-cascade/cases');$('#fast-case-selector').innerHTML=d.items.length?`<label>Saved challenge case<select id="fast-case-id">${d.items.map(r=>`<option>${esc(r.id)}</option>`).join('')}</select></label>`:'<p>No frozen challenge predictions yet.</p>';if(d.items.length)await drawFastCase();}catch(err){toast(err.message);}
});
document.addEventListener('change',e=>{if(e.target.id==='fast-case-id')drawFastCase().catch(err=>toast(err.message));});
async function drawFastCase(){
 const d=await api('fast-cascade/case?'+new URLSearchParams({id:$('#fast-case-id').value})),fields=Object.keys(d.expected),models=Object.keys(d.models),target=$('#fast-case-comparison');
 target.innerHTML=`<h3>${esc(d.id)}</h3><div class="source-text">${esc(d.text)}</div><div class="table-wrap"><table><thead><tr><th>Predicate</th><th>Truth</th>${models.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${fields.map(k=>`<tr><th>${esc(human(k))}</th><td>${esc(d.expected[k])}</td>${models.map(m=>{const value=d.observed?.[m]?.[k]??d.models[m].predicates?.[k]?.value??(k==='classification'?d.models[m].decision?.classification:null)??'NOT_SUPPORTED';return `<td class="${value!==d.expected[k]?'error-banner':''}">${esc(value)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${d.models.SELECTED_CASCADE?`<details><summary>Saved cascade trace</summary>${fastCascadeTrace({result:d.models.SELECTED_CASCADE})}</details>`:''}`;
 bindEvidence({text:d.text});
}

document.addEventListener('click',async e=>{
 if(e.target.id!=='analyse-fast-notice')return;
 const b=e.target;b.disabled=true;
 try{await api('fast-cascade/analyse',{method:'POST',body:JSON.stringify({record_id:b.dataset.record})});await openNotice(b.dataset.record);$('#fast-cascade-trace').open=true;toast('Cascade trace saved. Human review remains mandatory.');}catch(err){toast(err.message);b.disabled=false;}
});

async function fastCascadeConfidencePanel(){
 const d=await api('fast-cascade/status'),cal=d.calibration||{},coverage=d.confidence_coverage?.coverage||[],records=d.confidence_coverage?.records||[],bins=[];
 for(let i=0;i<10;i++){const r=records.filter(v=>v.confidence!=null&&v.confidence>=i/10&&(i===9?v.confidence<=1:v.confidence<(i+1)/10));if(r.length)bins.push({n:r.length,mean_probability:r.reduce((s,v)=>s+v.confidence,0)/r.length,observed_correctness:r.filter(v=>v.correct).length/r.length});}
 return panel('Three-gear confidence · synthetic population',`<div class="panel-body"><p>Separate Laya-first experiment: ${esc(d.state?.stage||'Preparing')}.</p><p>Confidence is unavailable until independent calibration supports each predicate. Minimum decisive trust is not a calibrated joint final-decision probability.</p>${Object.keys(cal).length?`<div class="table-wrap"><table><thead><tr><th>Predicate</th><th>Support / quality gate</th><th>Held-out Brier</th><th>Held-out ECE</th></tr></thead><tbody>${Object.entries(cal).map(([k,v])=>`<tr><td>${esc(human(k))}</td><td>${esc(v.status)}</td><td>${v.evaluation?.brier?.toFixed(4)??'Unavailable'}</td><td>${v.evaluation?.ece?.toFixed(4)??'Unavailable'}</td></tr>`).join('')}</tbody></table></div>`:'<p>Calibration fitting and evaluation are pending.</p>'}${bins.length?domainReliabilityPlot(bins):''}${coverage.length?`<div class="table-wrap"><table><thead><tr><th>Confidence threshold</th><th>Assertion coverage</th><th>Measured correctness</th><th>Would review</th><th>Accepted critical misses</th></tr></thead><tbody>${coverage.map(v=>`<tr><td>${v.threshold}</td><td>${pct(v.coverage)}</td><td>${v.measured_correctness==null?'Unavailable':pct(v.measured_correctness)}</td><td>${pct(v.review_rate)}</td><td>${v.accepted_critical_false_negatives}</td></tr>`).join('')}</tbody></table></div>`:''}<p>Simulation only. Actual human review remains mandatory.</p></div>`);
}
